mapper.select:
SELECT id,order_no,customer_id,status,channel,ordered_at,total_amount FROM sales_order

  customer_id=#{customerId}
  AND status=#{status}
  AND id < #{beforeId}

ORDER BY id DESC LIMIT #{limit}

SELECT o.*,c.name customer_name,w.name warehouse_name
FROM sales_order o JOIN customer c ON c.id=o.customer_id JOIN warehouse w ON w.id=o.warehouse_id
WHERE o.id=#{id}

SELECT o.id,o.order_no,o.customer_id,c.name customer_name,o.status,o.channel,o.ordered_at,o.paid_at,o.total_amount
FROM sales_order o JOIN customer c ON c.id=o.customer_id
WHERE o.order_no=#{orderNo}

SELECT o.id,o.order_no,o.customer_id,c.name customer_name,o.status,o.ordered_at,o.total_amount
FROM sales_order o JOIN customer c ON c.id=o.customer_id
ORDER BY o.total_amount DESC,o.id LIMIT #{offset},#{size}

SELECT a.customer_id,a.id first_order_id,a.order_no first_order_no,a.ordered_at first_ordered_at,
  b.id second_order_id,b.order_no second_order_no,b.ordered_at second_ordered_at,a.total_amount
FROM sales_order a JOIN sales_order b ON b.customer_id=a.customer_id AND b.id>a.id
  AND ABS(TIMESTAMPDIFF(HOUR,a.ordered_at,b.ordered_at))<=#{hours}
WHERE a.ordered_at>=#{from} AND a.ordered_at<#{until}
ORDER BY a.ordered_at,a.id,b.id
